// Spring Boot - Enable HTTP compression (built-in)
// application.properties or application.yml

# application.properties
# Enable response compression
server.compression.enabled=true

# Minimum response size to trigger compression (bytes)
# Default: 2048 (2KB) - only compress responses larger than this
server.compression.min-response-size=1024

# MIME types to compress
server.compression.mime-types=text/html,text/xml,text/plain,text/css,text/javascript,\
  application/javascript,application/json,application/xml,image/svg+xml

# Alternative: application.yml
server:
  compression:
    enabled: true
    min-response-size: 1024
    mime-types:
      - text/html
      - text/css
      - application/json

// For programmatic configuration:
// CompressionConfig.java

import org.springframework.boot.web.embedded.tomcat.TomcatServletWebServerFactory;
import org.springframework.boot.web.server.Compression;
import org.springframework.boot.web.server.WebServerFactoryCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class CompressionConfig {

    @Bean
    public WebServerFactoryCustomizer<TomcatServletWebServerFactory> compressionCustomizer() {
        return factory -> {
            Compression compression = new Compression();
            compression.setEnabled(true);
            compression.setMinResponseSize(DataSize.ofKilobytes(1));
            compression.setMimeTypes(new String[]{
                "text/html",
                "text/css",
                "application/javascript",
                "application/json"
            });
            factory.setCompression(compression);
        };
    }
}

spring-boot.testCode:
// JUnit test to verify compression
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@Test
public void shouldCompressResponseWhenAcceptEncodingGzip() throws Exception {
    mockMvc.perform(get("/")
            .header("Accept-Encoding", "gzip, deflate"))
        .andExpect(status().isOk())
        .andExpect(header().exists("Content-Encoding"));
}

express-nodejs.code:
// Express.js - Enable HTTP compression
const express = require('express');
const compression = require('compression');

const app = express();

// Enable compression
app.use(compression({
  level: 6,        // Compression level (0-9)
  threshold: 1024  // Only compress responses > 1KB
}));

app.get('/', (req, res) => {
  res.send('<html><body><h1>Compressed</h1></body></html>');
});

app.listen(3000);

