nginx.config:
# Nginx - Enable gzip compression
# /etc/nginx/nginx.conf

http {
    gzip on;
    gzip_comp_level 6;
    gzip_min_length 1024;
    gzip_proxied any;
    gzip_types text/plain text/css text/javascript application/javascript application/json;
    gzip_vary on;
}

